macro_rules! Capability {
    () => {
        # [doc = " Linux per-thread capability."] # [deprecated (since = "1.1.0" , note = "Use CapabilitySet with a single bit instead")] # [derive (Copy , Clone , Debug , Eq , PartialEq)] # [repr (u32)] # [non_exhaustive] pub enum Capability { # [doc = " In a system with the `_POSIX_CHOWN_RESTRICTED` option defined, this"] # [doc = " overrides the restriction of changing file ownership and group"] # [doc = " ownership."] ChangeOwnership = linux_raw_sys :: general :: CAP_CHOWN , # [doc = " Override all DAC access, including ACL execute access if `_POSIX_ACL`"] # [doc = " is defined. Excluding DAC access covered by"] # [doc = " [`Capability::LinuxImmutable`]."] DACOverride = linux_raw_sys :: general :: CAP_DAC_OVERRIDE , # [doc = " Overrides all DAC restrictions regarding read and search on files and"] # [doc = " directories, including ACL restrictions if `_POSIX_ACL` is defined."] # [doc = " Excluding DAC access covered by [`Capability::LinuxImmutable`]."] DACReadSearch = linux_raw_sys :: general :: CAP_DAC_READ_SEARCH , # [doc = " Overrides all restrictions about allowed operations on files, where"] # [doc = " file owner ID must be equal to the user ID, except where"] # [doc = " [`Capability::FileSetID`] is applicable. It doesn't override MAC and"] # [doc = " DAC restrictions."] FileOwner = linux_raw_sys :: general :: CAP_FOWNER , # [doc = " Overrides the following restrictions that the effective user ID shall"] # [doc = " match the file owner ID when setting the `S_ISUID` and `S_ISGID` bits"] # [doc = " on that file; that the effective group ID (or one of the supplementary"] # [doc = " group IDs) shall match the file owner ID when setting the `S_ISGID` bit"] # [doc = " on that file; that the `S_ISUID` and `S_ISGID` bits are cleared on"] # [doc = " successful return from `chown` (not implemented)."] FileSetID = linux_raw_sys :: general :: CAP_FSETID , # [doc = " Overrides the restriction that the real or effective user ID of a"] # [doc = " process sending a signal must match the real or effective user ID of"] # [doc = " the process receiving the signal."] Kill = linux_raw_sys :: general :: CAP_KILL , # [doc = " Allows `setgid` manipulation. Allows `setgroups`. Allows forged gids on"] # [doc = " socket credentials passing."] SetGroupID = linux_raw_sys :: general :: CAP_SETGID , # [doc = " Allows `set*uid` manipulation (including fsuid). Allows forged pids on"] # [doc = " socket credentials passing."] SetUserID = linux_raw_sys :: general :: CAP_SETUID , # [doc = " Without VFS support for capabilities:"] # [doc = "  - Transfer any capability in your permitted set to any pid."] # [doc = "  - remove any capability in your permitted set from any pid. With VFS"] # [doc = "    support for capabilities (neither of above, but)"] # [doc = "  - Add any capability from current's capability bounding set to the"] # [doc = "    current process' inheritable set."] # [doc = "  - Allow taking bits out of capability bounding set."] # [doc = "  - Allow modification of the securebits for a process."] SetPermittedCapabilities = linux_raw_sys :: general :: CAP_SETPCAP , # [doc = " Allow modification of `S_IMMUTABLE` and `S_APPEND` file attributes."] LinuxImmutable = linux_raw_sys :: general :: CAP_LINUX_IMMUTABLE , # [doc = " Allows binding to TCP/UDP sockets below 1024. Allows binding to ATM"] # [doc = " VCIs below 32."] NetBindService = linux_raw_sys :: general :: CAP_NET_BIND_SERVICE , # [doc = " Allow broadcasting, listen to multicast."] NetBroadcast = linux_raw_sys :: general :: CAP_NET_BROADCAST , # [doc = " Allow interface configuration. Allow administration of IP firewall,"] # [doc = " masquerading and accounting. Allow setting debug option on sockets."] # [doc = " Allow modification of routing tables. Allow setting arbitrary"] # [doc = " process / process group ownership on sockets. Allow binding to any"] # [doc = " address for transparent proxying (also via [`Capability::NetRaw`])."] # [doc = " Allow setting TOS (type of service). Allow setting promiscuous"] # [doc = " mode. Allow clearing driver statistics. Allow multicasting. Allow"] # [doc = " read/write of device-specific registers. Allow activation of ATM"] # [doc = " control sockets."] NetAdmin = linux_raw_sys :: general :: CAP_NET_ADMIN , # [doc = " Allow use of `RAW` sockets. Allow use of `PACKET` sockets. Allow"] # [doc = " binding to any address for transparent proxying (also via"] # [doc = " [`Capability::NetAdmin`])."] NetRaw = linux_raw_sys :: general :: CAP_NET_RAW , # [doc = " Allow locking of shared memory segments. Allow mlock and mlockall"] # [doc = " (which doesn't really have anything to do with IPC)."] IPCLock = linux_raw_sys :: general :: CAP_IPC_LOCK , # [doc = " Override IPC ownership checks."] IPCOwner = linux_raw_sys :: general :: CAP_IPC_OWNER , # [doc = " Insert and remove kernel modules - modify kernel without limit."] SystemModule = linux_raw_sys :: general :: CAP_SYS_MODULE , # [doc = " Allow ioperm/iopl access. Allow sending USB messages to any device via"] # [doc = " `/dev/bus/usb`."] SystemRawIO = linux_raw_sys :: general :: CAP_SYS_RAWIO , # [doc = " Allow use of `chroot`."] SystemChangeRoot = linux_raw_sys :: general :: CAP_SYS_CHROOT , # [doc = " Allow `ptrace` of any process."] SystemProcessTrace = linux_raw_sys :: general :: CAP_SYS_PTRACE , # [doc = " Allow configuration of process accounting."] SystemProcessAccounting = linux_raw_sys :: general :: CAP_SYS_PACCT , # [doc = " Allow configuration of the secure attention key. Allow administration"] # [doc = " of the random device. Allow examination and configuration of disk"] # [doc = " quotas. Allow setting the domainname. Allow setting the hostname."] # [doc = " Allow `mount` and `umount`, setting up new smb connection."] # [doc = " Allow some autofs root ioctls. Allow nfsservctl. Allow"] # [doc = " `VM86_REQUEST_IRQ`. Allow to read/write pci config on alpha. Allow"] # [doc = " `irix_prctl` on mips (setstacksize). Allow flushing all cache on"] # [doc = " m68k (`sys_cacheflush`). Allow removing semaphores. Used instead of"] # [doc = " [`Capability::ChangeOwnership`] to \"chown\" IPC message queues,"] # [doc = " semaphores and shared memory. Allow locking/unlocking of shared"] # [doc = " memory segment. Allow turning swap on/off. Allow forged pids on"] # [doc = " socket credentials passing. Allow setting readahead and"] # [doc = " flushing buffers on block devices. Allow setting geometry in floppy"] # [doc = " driver. Allow turning DMA on/off in `xd` driver. Allow"] # [doc = " administration of md devices (mostly the above, but some"] # [doc = " extra ioctls). Allow tuning the ide driver. Allow access to the nvram"] # [doc = " device. Allow administration of `apm_bios`, serial and bttv (TV)"] # [doc = " device. Allow manufacturer commands in isdn CAPI support driver."] # [doc = " Allow reading non-standardized portions of pci configuration space."] # [doc = " Allow DDI debug ioctl on sbpcd driver. Allow setting up serial ports."] # [doc = " Allow sending raw qic-117 commands. Allow enabling/disabling tagged"] # [doc = " queuing on SCSI controllers and sending arbitrary SCSI commands."] # [doc = " Allow setting encryption key on loopback filesystem. Allow setting"] # [doc = " zone reclaim policy. Allow everything under"] # [doc = " [`Capability::BerkeleyPacketFilters`] and"] # [doc = " [`Capability::PerformanceMonitoring`] for backward compatibility."] SystemAdmin = linux_raw_sys :: general :: CAP_SYS_ADMIN , # [doc = " Allow use of `reboot`."] SystemBoot = linux_raw_sys :: general :: CAP_SYS_BOOT , # [doc = " Allow raising priority and setting priority on other (different UID)"] # [doc = " processes. Allow use of FIFO and round-robin (realtime) scheduling"] # [doc = " on own processes and setting the scheduling algorithm used by"] # [doc = " another process. Allow setting cpu affinity on other processes."] # [doc = " Allow setting realtime ioprio class. Allow setting ioprio class on"] # [doc = " other processes."] SystemNice = linux_raw_sys :: general :: CAP_SYS_NICE , # [doc = " Override resource limits. Set resource limits. Override quota limits."] # [doc = " Override reserved space on ext2 filesystem. Modify data journaling"] # [doc = " mode on ext3 filesystem (uses journaling resources). NOTE: ext2"] # [doc = " honors fsuid when checking for resource overrides, so you can"] # [doc = " override using fsuid too. Override size restrictions on IPC message"] # [doc = " queues. Allow more than 64hz interrupts from the real-time clock."] # [doc = " Override max number of consoles on console allocation. Override max"] # [doc = " number of keymaps. Control memory reclaim behavior."] SystemResource = linux_raw_sys :: general :: CAP_SYS_RESOURCE , # [doc = " Allow manipulation of system clock. Allow `irix_stime` on mips. Allow"] # [doc = " setting the real-time clock."] SystemTime = linux_raw_sys :: general :: CAP_SYS_TIME , # [doc = " Allow configuration of tty devices. Allow `vhangup` of tty."] SystemTTYConfig = linux_raw_sys :: general :: CAP_SYS_TTY_CONFIG , # [doc = " Allow the privileged aspects of `mknod`."] MakeNode = linux_raw_sys :: general :: CAP_MKNOD , # [doc = " Allow taking of leases on files."] Lease = linux_raw_sys :: general :: CAP_LEASE , # [doc = " Allow writing the audit log via unicast netlink socket."] AuditWrite = linux_raw_sys :: general :: CAP_AUDIT_WRITE , # [doc = " Allow configuration of audit via unicast netlink socket."] AuditControl = linux_raw_sys :: general :: CAP_AUDIT_CONTROL , # [doc = " Set or remove capabilities on files. Map `uid=0` into a child user"] # [doc = " namespace."] SetFileCapabilities = linux_raw_sys :: general :: CAP_SETFCAP , # [doc = " Override MAC access. The base kernel enforces no MAC policy. An LSM may"] # [doc = " enforce a MAC policy, and if it does and it chooses to implement"] # [doc = " capability based overrides of that policy, this is the capability it"] # [doc = " should use to do so."] MACOverride = linux_raw_sys :: general :: CAP_MAC_OVERRIDE , # [doc = " Allow MAC configuration or state changes. The base kernel requires no"] # [doc = " MAC configuration. An LSM may enforce a MAC policy, and if it does and"] # [doc = " it chooses to implement capability based checks on modifications to"] # [doc = " that policy or the data required to maintain it, this is the capability"] # [doc = " it should use to do so."] MACAdmin = linux_raw_sys :: general :: CAP_MAC_ADMIN , # [doc = " Allow configuring the kernel's `syslog` (`printk` behaviour)."] SystemLog = linux_raw_sys :: general :: CAP_SYSLOG , # [doc = " Allow triggering something that will wake the system."] WakeAlarm = linux_raw_sys :: general :: CAP_WAKE_ALARM , # [doc = " Allow preventing system suspends."] BlockSuspend = linux_raw_sys :: general :: CAP_BLOCK_SUSPEND , # [doc = " Allow reading the audit log via multicast netlink socket."] AuditRead = linux_raw_sys :: general :: CAP_AUDIT_READ , # [doc = " Allow system performance and observability privileged operations using"] # [doc = " `perf_events`, `i915_perf` and other kernel subsystems."] PerformanceMonitoring = linux_raw_sys :: general :: CAP_PERFMON , # [doc = " This capability allows the following BPF operations:"] # [doc = "  - Creating all types of BPF maps"] # [doc = "  - Advanced verifier features"] # [doc = "     - Indirect variable access"] # [doc = "     - Bounded loops"] # [doc = "     - BPF to BPF function calls"] # [doc = "     - Scalar precision tracking"] # [doc = "     - Larger complexity limits"] # [doc = "     - Dead code elimination"] # [doc = "     - And potentially other features"] # [doc = "  - Loading BPF Type Format (BTF) data"] # [doc = "  - Retrieve `xlated` and JITed code of BPF programs"] # [doc = "  - Use `bpf_spin_lock` helper"] # [doc = ""] # [doc = " [`Capability::PerformanceMonitoring`] relaxes the verifier checks"] # [doc = " further:"] # [doc = "  - BPF progs can use of pointer-to-integer conversions"] # [doc = "  - speculation attack hardening measures are bypassed"] # [doc = "  - `bpf_probe_read` to read arbitrary kernel memory is allowed"] # [doc = "  - `bpf_trace_printk` to print kernel memory is allowed"] # [doc = ""] # [doc = " [`Capability::SystemAdmin`] is required to use `bpf_probe_write_user`."] # [doc = ""] # [doc = " [`Capability::SystemAdmin`] is required to iterate system-wide loaded"] # [doc = " programs, maps, links, and BTFs, and convert their IDs to file"] # [doc = " descriptors."] # [doc = ""] # [doc = " [`Capability::PerformanceMonitoring`] and"] # [doc = " [`Capability::BerkeleyPacketFilters`] are required to load tracing"] # [doc = " programs. [`Capability::NetAdmin`] and"] # [doc = " [`Capability::BerkeleyPacketFilters`] are required to load"] # [doc = " networking programs."] BerkeleyPacketFilters = linux_raw_sys :: general :: CAP_BPF , # [doc = " Allow checkpoint/restore related operations. Allow PID selection during"] # [doc = " `clone3`. Allow writing to `ns_last_pid`."] CheckpointRestore = linux_raw_sys :: general :: CAP_CHECKPOINT_RESTORE , }
    };
}

Capability!()